package justepicdimensions.monitor;

import com.google.gson.*;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.*;
import justepicdimensions.JustEpicDimensions;
import justepicdimensions.admin.*;
import justepicdimensions.definition.*;
import justepicdimensions.dimension.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.network.chat.Component;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.*;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Native counters are copied on the server thread; filesystem work consumes detached values. */
@EventBusSubscriber(modid=JustEpicDimensions.ID)
public final class JEDMonitoringController {
 public record Prepared(boolean enabled,JEDMonitoringPolicy global,Map<ResourceLocation,JEDMonitoringPolicy> policies,Map<ResourceLocation,JEDMonitoringPolicy.Binding> bindings){}
 private static final Map<MinecraftServer,Owner> OWNERS=new IdentityHashMap<>();
 private static final Map<MinecraftServer,Map<ResourceLocation,Integer>> EPOCHS=new IdentityHashMap<>();
 @SubscribeEvent public static void loaded(net.neoforged.neoforge.event.level.LevelEvent.Load e){if(e.getLevel() instanceof net.minecraft.server.level.ServerLevel level)EPOCHS.computeIfAbsent(level.getServer(),k->new HashMap<>()).put(level.dimension().location(),level.getServer().getTickCount());}
 @SubscribeEvent public static void unloaded(net.neoforged.neoforge.event.level.LevelEvent.Unload e){if(e.getLevel() instanceof net.minecraft.server.level.ServerLevel level){var epochs=EPOCHS.get(level.getServer());if(epochs!=null)epochs.remove(level.dimension().location());}}
 private static final class State{long next,lastDisk;JsonObject last=new JsonObject();JEDMonitoringDisk.Reading disk;String diskError;boolean scanning;final Map<String,Alert> alerts=new HashMap<>();final ArrayDeque<JsonObject> recent=new ArrayDeque<>();JEDMonitoringPolicy policy;}
 public static final class Alert{long began=-1,clear=-1;boolean active;String blocked="";public boolean active(){return active;}public boolean evaluate(JEDMonitoringPolicy.Rule rule,double value,long now){boolean old=active;if(value>rule.above()){clear=-1;if(began<0)began=now;if(now-began>=rule.delaySeconds()*1000L)active=true;}else if(value<=rule.clearBelow()){began=-1;if(clear<0)clear=now;if(now-clear>=rule.recoverySeconds()*1000L)active=false;}else{began=-1;clear=-1;}return old!=active;}}
 private static final class Owner{
  final MinecraftServer server;final Path world;final JEDMonitoringHistory history;final ThreadPoolExecutor io=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(256),Thread.ofPlatform().daemon(true).name("JED monitoring IO").factory());final Map<ResourceLocation,State> states=new HashMap<>();final ThreadPoolExecutor scans=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(128),Thread.ofPlatform().daemon(true).name("JED monitoring disk").factory());Prepared config;Iterator<ResourceLocation> pending=Collections.emptyIterator();long cycle,maintenance;boolean stopping;String error="";
  Owner(MinecraftServer server,Prepared config){this.server=server;this.config=config;world=server.getWorldPath(LevelResource.ROOT).toAbsolutePath().normalize();history=new JEDMonitoringHistory(world);}
 }
 public static Prepared prepare(JEDPreparedDefinitions candidate,Map<ResourceLocation,JEDDimensionDefinition> definitions){var all=candidate.monitoringPolicies();var config=candidate.activeMainConfig();String name=config.get("monitoringPolicy").getAsString();var global=name.isEmpty()?JEDMonitoringPolicy.defaults():all.get(JEDDimensionDefinition.id(name,"monitoringPolicy"));if(global==null)throw new JEDDefinitionException("Unknown global monitoring policy "+name);var bindings=new TreeMap<ResourceLocation,JEDMonitoringPolicy.Binding>();definitions.forEach((id,d)->{var binding=JEDMonitoringPolicy.binding(d.source().value().getAsJsonObject());if(binding.policy()!=null&&!all.containsKey(binding.policy()))throw new JEDDefinitionException(id+": unknown monitoring policy "+binding.policy());bindings.put(id,binding);});return new Prepared(config.get("monitoringEnabled").getAsBoolean(),global,all,Map.copyOf(bindings));}
 public static void publish(MinecraftServer server,Prepared config){var owner=OWNERS.computeIfAbsent(server,s->new Owner(s,config));owner.config=config;owner.cycle=0;var retention=new HashMap<ResourceLocation,JEDMonitoringPolicy>();for(var id:JEDAdminSnapshot.ids(server))retention.put(id,policy(owner,id));final Owner target=owner;work(owner,()->{for(var e:retention.entrySet()){target.history.configure(e.getKey(),e.getValue(),false);target.history.clean(e.getKey(),e.getValue(),System.currentTimeMillis());}return null;});for(var e:owner.states.entrySet()){var policy=policy(owner,e.getKey());if(!Objects.equals(e.getValue().policy,policy)||!enabled(owner,e.getKey())){e.getValue().alerts.clear();e.getValue().next=0;justepicdimensions.pregen.JEDPregenerationController.monitoringPause(server,e.getKey(),false);}}}
 private static JEDMonitoringPolicy policy(Owner o,ResourceLocation id){var b=o.config.bindings().get(id);return b!=null&&b.policy()!=null?o.config.policies().get(b.policy()):o.config.global();}
 private static boolean enabled(Owner o,ResourceLocation id){if(!JEDDimensionLifecycle.enabled(o.server,id))return false;var b=o.config.bindings().get(id);return b!=null&&b.enabled()!=null?b.enabled():o.config.enabled();}
 public static JsonObject sample(MinecraftServer server,ResourceLocation id,long now){JEDAdminSnapshot.thread(server);var j=new JsonObject();j.addProperty("time",now);var level=server.levels.get(ResourceKey.create(Registries.DIMENSION,id));j.addProperty("loaded",level!=null);if(level!=null){j.addProperty("players",level.players().size());j.addProperty("loaded_chunks",level.getChunkSource().getLoadedChunksCount());j.addProperty("loaded_entities",level.entityManager.count());var times=server.getTickTime(level.dimension());if(times!=null){int count=Math.max(0,Math.min(times.length,server.getTickCount()-EPOCHS.getOrDefault(server,Map.of()).getOrDefault(id,server.getTickCount()-times.length)));double[] values=java.util.stream.IntStream.range(0,count).mapToLong(i->times[Math.floorMod(server.getTickCount()-i,times.length)]).filter(n->n>0).mapToDouble(n->n/1000000.0).sorted().toArray();if(values.length>0){j.addProperty("tick_ms_mean",Arrays.stream(values).average().orElse(0));j.addProperty("tick_ms_p95",values[Math.min(values.length-1,(int)Math.ceil(values.length*.95)-1)]);j.addProperty("tick_ms_max",values[values.length-1]);j.addProperty("tick_samples",values.length);}}}return j;}
 @SubscribeEvent public static void tick(ServerTickEvent.Post event){var o=OWNERS.get(event.getServer());if(o==null||o.stopping)return;try{collect(o);}catch(RuntimeException error){if(!error.toString().equals(o.error)){o.error=error.toString();notice(o,"monitoring sample failed: "+error.getMessage());}}}
 private static void collect(Owner o){long now=System.currentTimeMillis();if(now>=o.maintenance){o.maintenance=now+3600000L;work(o,()->{o.history.maintenance(now);return null;});}if(!o.pending.hasNext()&&now>=o.cycle){o.pending=JEDAdminSnapshot.ids(o.server).iterator();o.cycle=now+1000;}long start=System.nanoTime();for(int count=0;count<8&&o.pending.hasNext()&&System.nanoTime()-start<2_000_000;count++){var id=o.pending.next();if(!enabled(o,id)){var previous=o.states.get(id);if(previous!=null&&!previous.alerts.isEmpty()){previous.alerts.clear();justepicdimensions.pregen.JEDPregenerationController.monitoringPause(o.server,id,false);}continue;}var state=o.states.computeIfAbsent(id,k->new State());var p=policy(o,id);if(now<state.next)continue;state.policy=p;state.next=now+p.sampleSeconds()*1000L;var row=sample(o.server,id,now);if(state.disk!=null)state.disk.json().entrySet().forEach(e->row.add(e.getKey(),e.getValue()));state.last=row;state.recent.addLast(row.deepCopy());long cutoff=now-1000L*(p.mode().equals("session")?p.retentionSeconds():Math.min(p.retentionSeconds(),Math.max(3600,p.detailSeconds())));while(!state.recent.isEmpty()&&(state.recent.getFirst().get("time").getAsLong()<cutoff||!p.mode().equals("session")&&state.recent.size()>1000))state.recent.removeFirst();work(o,()->{o.history.add(id,p,row);return null;});evaluate(o,id,state,row,now);if(!state.scanning&&(state.lastDisk==0||now-state.lastDisk>=p.diskSeconds()*1000L))disk(o,id);}}
 private static void evaluate(Owner o,ResourceLocation id,State state,JsonObject row,long now){boolean pause=false;for(var rule:state.policy.rules()){var a=state.alerts.computeIfAbsent(rule.id(),k->new Alert());if(row.has(rule.metric())&&(!rule.metric().startsWith("disk_")||state.diskError==null)){if(a.evaluate(rule,row.get(rule.metric()).getAsDouble(),now))notice(o,"Dimension "+id+": monitoring alert "+rule.id()+" "+(a.active?"active":"cleared")+" ("+rule.metric()+"="+row.get(rule.metric())+")");}if(!a.active)continue;pause|=rule.actions().contains("pause_pregeneration");if(rule.actions().contains("unload")){String blocked=JEDAdminUnloader.reason(o.server,id,false);a.blocked=blocked==null?"":blocked;if(blocked==null)try{JEDDimensionManager.unload(o.server,id);}catch(RuntimeException failure){a.blocked=failure.getMessage();}}}justepicdimensions.pregen.JEDPregenerationController.monitoringPause(o.server,id,pause);}
 private static void notice(Owner o,String message){com.mojang.logging.LogUtils.getLogger().warn("JED {}",message);for(var player:o.server.getPlayerList().getPlayers())if(player.hasPermissions(2))player.sendSystemMessage(Component.literal("[JED] "+message));}
 private static <T> CompletableFuture<T> work(Owner o,Callable<T> task){return work(o,task,o.io);}
 private static <T> CompletableFuture<T> work(Owner o,Callable<T> task,ThreadPoolExecutor executor){var result=new CompletableFuture<T>();try{executor.execute(()->{try{result.complete(task.call());}catch(Throwable error){result.completeExceptionally(error);if(!o.stopping)o.server.execute(()->{if(OWNERS.get(o.server)==o&&!o.stopping&&!error.toString().equals(o.error)){o.error=error.toString();notice(o,"monitoring IO failed: "+error.getMessage());}});}});}catch(RejectedExecutionException error){result.completeExceptionally(error);if(!o.stopping&&!error.toString().equals(o.error)){o.error=error.toString();notice(o,"monitoring IO queue is full; history may have gaps");}}return result;}
 private static CompletableFuture<Void> disk(Owner o,ResourceLocation id){var s=o.states.computeIfAbsent(id,k->new State());if(s.scanning)return CompletableFuture.completedFuture(null);s.scanning=true;s.lastDisk=System.currentTimeMillis();var ids=Set.copyOf(JEDAdminSnapshot.ids(o.server));long revision=JEDDefinitionManager.state(o.server).revision();return work(o,()->JEDMonitoringDisk.measure(o.world,id,ids),o.scans).handleAsync((reading,error)->{if(OWNERS.get(o.server)!=o||o.stopping)return null;s.scanning=false;if(JEDDefinitionManager.state(o.server).revision()!=revision){s.diskError="Definitions changed during disk scan; refresh again";s.lastDisk=0;return null;}if(error!=null){s.diskError=error.getMessage();if(error instanceof RejectedExecutionException)s.lastDisk=0;}else{s.disk=reading;s.diskError=null;}return null;},o.server);}
 public static CompletableFuture<JsonObject> view(MinecraftServer server,JsonObject request){JEDAdminSnapshot.thread(server);var o=OWNERS.get(server);if(o==null)return CompletableFuture.failedFuture(new JEDDefinitionException("Monitoring has not initialized"));String action=request.has("action")?JEDJson.string(request.get("action"),"action"):"status";ResourceLocation selected=request.has("dimension")&&!request.get("dimension").getAsString().isEmpty()?JEDDimensionDefinition.id(JEDJson.string(request.get("dimension"),"dimension"),"monitor dimension"):null;if(selected!=null&&!JEDAdminSnapshot.ids(server).contains(selected))throw new JEDDefinitionException("Unknown monitored dimension "+selected);if(action.equals("disk")){if(selected==null)throw new JEDDefinitionException("Select a dimension for disk refresh");disk(o,selected);var basic=statusRequest(request);basic.addProperty("no_history",true);return view(server,basic);}if(!action.equals("status"))throw new JEDDefinitionException("Unknown monitoring action");
  int page=request.has("page")?JEDJson.integer(request.get("page"),"page"):1;int size=request.has("page_size")?JEDJson.integer(request.get("page_size"),"page_size"):8;if(!Set.of(8,12,16,24,32).contains(size))throw new JEDDefinitionException("Monitoring page size must be 8, 12, 16, 24 or 32");var nativePage=JEDAdminSnapshot.page(server,JEDAdminSnapshot.Filter.ALL,page,size);var out=new JsonObject();out.addProperty("kind","monitoring");out.addProperty("time",System.currentTimeMillis());out.addProperty("page",nativePage.number());out.addProperty("page_size",size);out.addProperty("pages",nativePage.pages());out.addProperty("total",nativePage.total());out.addProperty("io_error",o.error);var rows=new JsonArray();for(var row:nativePage.rows())rows.add(row(o,row.id(),row.data()));out.add("dimensions",rows);if(selected==null)return CompletableFuture.completedFuture(out);out.add("selected",row(o,selected,JEDAdminSnapshot.row(server,selected,false).data()));if(request.has("no_history"))return CompletableFuture.completedFuture(out);var p=policy(o,selected);String metric=request.has("metric")?JEDJson.string(request.get("metric"),"metric"):"tick_ms_mean";if(!JEDMonitoringPolicy.METRICS.contains(metric))throw new JEDDefinitionException("Unknown monitoring metric "+metric);long seconds=request.has("seconds")?JEDJson.integer(request.get("seconds"),"seconds"):3600;if(seconds<1)throw new JEDDefinitionException("Positive history range required");long now=System.currentTimeMillis(),since=now-Math.min(seconds,(long)p.retentionSeconds())*1000L;out.addProperty("metric",metric);
  if(p.mode().equals("session")){var points=new JsonArray();var buckets=new TreeMap<Long,JEDMonitoringHistory.Point>();long width=Math.max(1,(now-since+999)/1000);var s=o.states.get(selected);if(s!=null)for(var r:s.recent)if(r.get("time").getAsLong()>=since&&r.get("time").getAsLong()<=now&&r.has(metric))buckets.computeIfAbsent((r.get("time").getAsLong()-since)/width,k->new JEDMonitoringHistory.Point()).add(r.get("time").getAsLong(),r.get(metric).getAsDouble());buckets.values().forEach(pnt->points.add(pnt.json()));out.add("points",points);return CompletableFuture.completedFuture(out);}return work(o,()->{var data=o.history.query(selected,p,since,now,metric);data.entrySet().forEach(e->out.add(e.getKey(),e.getValue()));return out;});
 }
 private static JsonObject statusRequest(JsonObject original){var r=original.deepCopy();r.addProperty("action","status");return r;}
 private static JsonObject row(Owner o,ResourceLocation id,JsonObject row){var s=o.states.get(id);var p=policy(o,id);row.addProperty("recording",enabled(o,id));row.addProperty("history_mode",p.mode());row.addProperty("sample_seconds",p.sampleSeconds());row.addProperty("retention_seconds",p.retentionSeconds());row.addProperty("disk_refresh_seconds",p.diskSeconds());var current=sample(o.server,id,System.currentTimeMillis());current.entrySet().forEach(e->row.add(e.getKey(),e.getValue()));var alerts=new JsonArray();if(s!=null){if(s.disk!=null)s.disk.json().entrySet().forEach(e->row.add(e.getKey(),e.getValue()));if(s.diskError!=null)row.addProperty("disk_error",s.diskError);row.addProperty("disk_scanning",s.scanning);s.alerts.forEach((name,a)->{if(a.active){var j=new JsonObject();j.addProperty("id",name);j.addProperty("blocked",a.blocked);alerts.add(j);}});}row.add("alerts",alerts);return row;}
 public static JsonObject diagnostics(MinecraftServer server,ResourceLocation id){var o=OWNERS.get(server);if(o==null)return new JsonObject();var row=new JsonObject();row.addProperty("recording",enabled(o,id));var s=o.states.get(id);if(s!=null&&s.disk!=null)s.disk.json().entrySet().forEach(e->row.add(e.getKey(),e.getValue()));if(!o.error.isEmpty())row.addProperty("io_error",o.error);return row;}
 public static CompletableFuture<Void> flush(MinecraftServer server){var o=OWNERS.get(server);return o==null?CompletableFuture.completedFuture(null):work(o,()->null);}
 @SubscribeEvent public static void stopping(ServerStoppingEvent event){var o=OWNERS.get(event.getServer());if(o==null)return;o.stopping=true;o.scans.shutdownNow();try{work(o,()->{o.history.finish();return null;}).get(15,TimeUnit.SECONDS);}catch(Exception e){com.mojang.logging.LogUtils.getLogger().error("JED monitoring history could not finish",e);}finally{o.io.shutdown();}}
 @SubscribeEvent public static void stopped(ServerStoppedEvent event){EPOCHS.remove(event.getServer());var o=OWNERS.remove(event.getServer());if(o!=null){o.io.shutdownNow();o.scans.shutdownNow();}}
 private JEDMonitoringController(){}
}
